1	package registrymgr
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"log"
9		"net/http"
10		"net/url"
11		"strings"
12		"time"
13	)
14	
15	func init() {
16		Register(&NexusDetector{})
17	}
18	
19	// NexusDetector handles Sonatype Nexus Repository Manager group repositories.
20	// Two URL formats are supported:
21	//  1. Path-based:   https://nexus.example.com/repository/docker-group
22	//  2. Subdomain:    nexus-docker-group.example.com  (requires info.ManagementURL)
23	//
24	// Which one applies is read from the URL. Whether this detector runs at all is
25	// not: that is the declared provider's decision (§3.8, decision F).
26	type NexusDetector struct{}
27	
28	var nexusHTTPClient = &http.Client{Timeout: 8 * time.Second}
29	
30	// Provider returns the provider this detector serves.
31	func (n *NexusDetector) Provider() string { return ProviderNexus }
32	
33	// DetectGroup calls the Nexus REST API to determine whether the registry points
34	// to a group repository and, if so, returns its member repositories.
35	//
36	// Returns nil, nil when the manager answered and the repository is not a group,
37	// and an error when it could not be asked. Those two are not the same thing:
38	// the caller caches the first and must not cache the second, or one unreachable
39	// minute erases what was last known (D23).
40	func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
41		// Resolve which URL to use for the Nexus API call.
42		apiBase := info.ManagementURL
43		if apiBase == "" {
44			apiBase = info.URL
45		}
46	
47		host, repoName, err := parseNexusURL(apiBase)
48		if err != nil {
49			// Not an error: a URL that is not a Nexus repository path is a settled
50			// answer, not a failure to reach one.
51			log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL %q: %v", apiBase, err)
52			return nil, nil
53		}
54	
55		hasAuth := info.Username != "" && info.Password != ""
56		log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
57	
58		// Step 1: generic endpoint — confirms this repo is a group, gets its format,
59		// and may already include memberNames in the attributes field (no admin privilege needed).
60		repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
61		if err != nil {
62			return nil, err
63		}
64		if repoType != "group" {
65			return nil, nil
66		}
67	
68		if len(members) > 0 {
69			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
70			return members, nil
71		}
72	
73		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
74		// but returns memberNames reliably on Nexus instances that support it.
75		members = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
76		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
77		return members, nil
78	}
79	
80	// fetchRepoMeta calls the generic /v1/repositories/{name} endpoint.
81	// Returns type, format and any memberNames found in attributes, or an error when
82	// the manager could not be asked.
83	// Some Nexus deployments include memberNames in attributes.group without requiring admin privilege.
84	func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string, info RegistryInfo) (repoType, format string, members []GroupMember, err error) {
85		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
86		body, err := n.nexusGET(ctx, endpoint, info)
87		if err != nil {
88			log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
89			return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
90		}
91		var result struct {
92			Type   string `json:"type"`
93			Format string `json:"format"`
94			Group  struct {
95				MemberNames []string `json:"memberNames"`
96			} `json:"group"`
97			Attributes struct {
98				Group struct {
99					MemberNames []string `json:"memberNames"`
100				} `json:"group"`
101			} `json:"attributes"`
102		}
103		if err := json.Unmarshal(body, &result); err != nil {
104			log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
105			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, err)
106		}
107		log.Printf("INFO [registrymgr/nexus] meta %q: type=%s format=%s", repoName, result.Type, result.Format)
108	
109		// Collect memberNames from whichever field Nexus populated.
110		rawNames := result.Group.MemberNames
111		if len(rawNames) == 0 {
112			rawNames = result.Attributes.Group.MemberNames
113		}
114		members = memberList(info.URL, rawNames)
115		return result.Type, result.Format, members, nil
116	}
117	
118	// fetchGroupMembers calls the format-specific group endpoint which reliably
119	// includes memberNames: GET /v1/repositories/{format}/group/{name}
120	// Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
121	func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) []GroupMember {
122		if format == "" {
123			format = "docker"
124		}
125		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, format, repoName)
126		body, err := n.nexusGET(ctx, endpoint, info)
127		if err != nil {
128			// When auth is present but the request fails, retry anonymously.
129			// Some Nexus instances allow anonymous read of the group admin endpoint.
130			if info.Username != "" && info.Password != "" {
131				anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
132				body, err = n.nexusGET(ctx, endpoint, anonInfo)
133			}
134		}
135		if err != nil {
136			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
137			return nil
138		}
139		var result struct {
140			Group struct {
141				MemberNames []string `json:"memberNames"`
142			} `json:"group"`
143		}
144		if err := json.Unmarshal(body, &result); err != nil {
145			return nil
146		}
147		return memberList(info.URL, result.Group.MemberNames)
148	}
149	
150	// memberList turns the names a group declares into addresses.
151	func memberList(dockerURL string, names []string) []GroupMember {
152		members := make([]GroupMember, 0, len(names))
153		for _, name := range names {
154			url, prefix := memberAddress(dockerURL, name)
155			members = append(members, GroupMember{
156				Alias:      cleanMemberAlias(name),
157				URL:        url,
158				RepoPrefix: prefix,
159			})
160		}
161		return members
162	}
163	
164	// memberAddress decides how one member of a group is reached, from the URL the
165	// group itself is pulled from.
166	//
167	// A group written as a path prefix — `host/repository/<group>` — is an instance
168	// serving its Docker repositories that way, so its members are reached the same
169	// way: the host, with the member's name in front of the repository. That pair is
170	// consistent by construction, because browse and pull build the same path from
171	// it.
172	//
173	// Anything else is a connector of the group's own — a dedicated port, a
174	// subdomain — and says nothing about a member. Which of those a repository
175	// answers on is a setting on that repository (`docker.httpPort`,
176	// `docker.httpsPort`, `docker.subdomain`), and the endpoint carrying it is
177	// refused to an ordinary pull account. So nothing is claimed: the member is
178	// offered at the group's own address with no prefix, which browses to nothing
179	// visibly rather than pulling to nothing plausibly (§3.18).
180	func memberAddress(dockerURL, memberName string) (url, prefix string) {
181		host, _, err := parseNexusURL(dockerURL)
182		if err != nil {
183			return dockerURL, ""
184		}
185		// parseNexusURL supplies https:// for a URL written without a scheme. The
186		// group's own spelling is what the rest of the application is keyed on, so
187		// it is kept rather than normalised here.
188		if !strings.Contains(strings.ToLower(dockerURL), "://") {
189			host = strings.TrimPrefix(host, "https://")
190		}
191		return host, memberName
192	}
193	
194	// nexusGET performs an authenticated GET and returns the response body.
195	func (n *NexusDetector) nexusGET(ctx context.Context, endpoint string, info RegistryInfo) ([]byte, error) {
196		req, err := http.NewRequestWithContext(ctx, "GET", endpoint, nil)
197		if err != nil {
198			return nil, err
199		}
200		if info.Username != "" && info.Password != "" {
201			req.SetBasicAuth(info.Username, info.Password)
202		}
203		resp, err := nexusHTTPClient.Do(req)
204		if err != nil {
205			return nil, err
206		}
207		defer func() { _ = resp.Body.Close() }()
208		if resp.StatusCode != http.StatusOK {
209			return nil, fmt.Errorf("HTTP %d", resp.StatusCode)
210		}
211		var buf []byte
212		buf, err = io.ReadAll(resp.Body)
213		return buf, err
214	}
215	
216	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
217	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
218	func parseNexusURL(registryURL string) (host, repoName string, err error) {
219		raw := registryURL
220		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
221			raw = "https://" + raw
222		}
223		u, err := url.Parse(raw)
224		if err != nil {
225			return "", "", err
226		}
227		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
228		// Expected: ["repository", "<repoName>", ...]
229		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
230			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
231		}
232		host = u.Scheme + "://" + u.Host
233		repoName = parts[1]
234		return host, repoName, nil
235	}
236	
237	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
238	func cleanMemberAlias(name string) string {
239		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
240			if strings.HasSuffix(name, suffix) {
241				return name[:len(name)-len(suffix)]
242			}
243		}
244		return name
245	}
246

